import{_ as s,l as r,o as a,c,v as l,p as d,x as o,d as i,i as p,S as n}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"select 与 poll","description":"","frontmatter":{"title":"select 与 poll","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/select-poll.md","filePath":"cs/select-poll.md","lastUpdated":1789023840000}'),E={name:"cs/select-poll.md"};function h(f,e,m,_,B,u){const t=r("Mermaid");return a(),c("div",null,[e[1]||(e[1]=l('<h1 id="select-与-poll" tabindex="-1">select 与 poll <a class="header-anchor" href="#select-与-poll" aria-label="Permalink to &quot;select 与 poll&quot;">​</a></h1><div class="epigraph"><p>一次系统调用等待一组描述符上的可读、可写或异常；内核在任一就绪或超时后返回就绪集合。</p><footer>—— 据 POSIX select/poll；Stevens, UNIX Network Programming 整理</footer></div><p><a href="/cs/posix-shm">上一课</a>解决大块数据，没解决「许多通道何时有事件」。为每个 FIFO/套接字 fork 一个进程会炸。<a href="/cs/sigmask">信号掩码</a> 的 pselect 已预告原子等。缺口是 <strong>I/O 多路复用</strong>：把睡眠从「一个 fd 的 read」变成「一组 fd 的就绪」。本课合并 select 与 poll，对照它们的接口裂缝。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>read</code> 阻塞在一个 fd 上时，别的 fd 就绪也无法处理。非阻塞轮询浪费 CPU。<a href="/cs/scheduling-metrics">调度</a> 需要可睡眠的等待。select：位图 <code>fd_set</code>，容量受 <code>FD_SETSIZE</code> 限制，每次调用内核扫描并改写位图。poll：<code>pollfd</code> 数组，无固定 1024 上限，仍要每次把数组拷进内核并线性扫描。缺口不是 epoll 的就绪队列——那是下一课。</p><p><span class="marginnote">就绪指：读不会阻塞（有数据或 EOF）、写不会阻塞（缓冲有空），或错误。水平触发：只要条件仍成立，下次还会报告。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户填集合，陷入内核。内核把进程挂到这些文件对象的等待队列上，超时用后课 jiffies/hrtimer 的睡眠。任一设备下半部唤醒对应队列，扫描集合，拷回就绪项，返回个数。与 <a href="/cs/ipc-pipe">管道</a> 满/空睡眠是同一唤醒源，只是等待者在等「集合」而非单端。</p>',8)),(a(),d(n,null,{default:o(()=>[p(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SET%5B%22fd%20%E9%9B%86%E5%90%88%22%5D%20--%3E%20SLEEP%5B%22%E6%8C%82%E5%88%B0%E5%90%84%E6%96%87%E4%BB%B6%E7%AD%89%E5%BE%85%E9%98%9F%E5%88%97%22%5D%0A%20%20SLEEP%20--%3E%20EVT%5B%22%E4%BB%BB%E4%B8%80%E5%B0%B1%E7%BB%AA%E6%88%96%E8%B6%85%E6%97%B6%22%5D%0A%20%20EVT%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E5%B0%B1%E7%BB%AA%E5%AD%90%E9%9B%86%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>select/poll 让单线程事件循环成为可能：Web 服务器经典模型的起点。代价是 O(n) 每次调用。它们不代替 <a href="/cs/vfs">VFS</a> 的 <code>read</code>；只告诉你现在调用 <code>read</code> 是否会睡。Unix 域、FIFO、后来的网卡套接字都实现同一 poll 操作向量。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>epoll</code> 提前当解决方案写完。不引入 Windows <code>WaitForMultipleObjects</code> 对照考试。信号与 I/O 同时等用 pselect，避免竞态。下一课针对「n 很大、每次就绪很少」改兴趣表。</p><p>后课默认：可以等一组 fd。规模上升后的兴趣表与边沿触发，下一课 epoll。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>select/poll 睡眠等待集合就绪，水平触发。</li><li>每次调用扫描全部兴趣 fd，有规模问题。</li><li>内核侧就绪队列是 epoll 的缺口。</li><li>出处：POSIX；Stevens, <em>UNP</em>；Tanenbaum <em>MOS</em>。</li></ul>',7))])}const P=s(E,[["render",h]]);export{T as __pageData,P as default};
